cat > tests/forms_test.sh <<'EOF'
#!/bin/bash
fail=0
bash bin/render event | grep -q 'action=' || { echo "render"; fail=1; }
# Every rendered form URL must use only query-string key characters Cirrus accepts (A-Z a-z 0-9 _ . -)
for f in event seat refund; do
  bash bin/render $f | grep -o 'action="[^"]*"' | sed 's/^action="//;s/"$//' | while read -r u; do
    key=${u#\?}; key=${key%%=*}
    [[ "$key" =~ ^[A-Za-z0-9_.-]+$ ]] || { echo "invalid query key: $u"; exit 1; }
  done || fail=1
done
bash bin/handle POST '/events/1/edit?action=save' | grep -q '^200 save' || { echo "handle"; fail=1; }
bash bin/handle POST '/events/1/seats?action=assign' | grep -q '^200 assign' || { echo "handle assign"; fail=1; }
bash bin/handle POST '/orders/1/refund?action=refund' | grep -q '^200 refund' || { echo "handle refund"; fail=1; }
bash bin/handle POST '/events/1/edit?action=nope' | grep -q '^404' || { echo "unknown action"; fail=1; }
exit $fail
EOF
bash scripts/verify.sh; echo rc=$?
cat > lib/actions.sh <<'EOF'
#!/bin/bash
# Form actions: a form posts to its own page with the action named in the query (?action=name).
# The key must stay within A-Z a-z 0-9 _ . - : the Cirrus function URL rejects other characters (docs/platform/cirrus-functions.md).
action_url() { echo "?action=$1"; }
# Prints the action named by a query string, or nothing.
action_from_query() { case "$1" in action=*) a=${1#action=}; echo "${a%%&*}" ;; esac; }
EOF
sed -i 's|`?/<操作名>`|`?action=<操作名>`（キーに `/` などは使えない。Cirrus の関数 URL が 400 で弾く）|' docs/framework.md
bash scripts/verify.sh; echo rc=$?
